advisory.suggested_fix:
Add a parametrized test, e.g.:
@pytest.mark.parametrize("bad", ["see https://notpandoc.org", "see https://pandoc.org.evil.com", "see https://github.com/jgm/pandoc-extras"])
def test_lookalike_upstream_hosts_are_rejected(bad):
    assert _UPSTREAM_RE.search(bad) is None
@pytest.mark.parametrize("ok", ["https://pandoc.org", "https://www.pandoc.org/x", "https://github.com/jgm/pandoc"])
def test_real_upstream_urls_are_accepted(ok):
    assert _UPSTREAM_RE.search(ok) is not None
